-- Generated by build_world_batch.py. See its docstring and each
-- region's notes; style.json holds every claim's sources.

begin;

insert into public.wine_regions
  (region_code, name, aliases, country_code, latitude, longitude, radius_km,
   summary, red_body, red_acidity, red_tannin, pairing, label_note,
   source_url, publication_status)
values
  ('wr_0213', 'Moravia', '{"Morava"}'::text[], 'CZ', 48.957, 16.850, 38,
   'Moravia sits mostly in the warm Pannonian zone, with continental influence. Vines grow on loess, limestone and sands; about two thirds of the area is white, giving aromatic whites with fresh acidity and soft, fruity reds.',
   null, null, 2, null, 'Quality wine needs at least 15 °NM must weight. Predicate wines (jakostní víno s přívlastkem) rise by ripeness: kabinetní víno 19 °NM, pozdní sběr 21, výběr z hroznů 24, výběr z bobulí, ledové víno and slámové víno 27, výběr z cibéb 32.',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/17074', 'published'),
  ('wr_0214', 'Dealu Mare', '{"Dealul Mare"}'::text[], 'RO', 45.085, 26.456, 18,
   'Hill vineyards in Prahova and Buzău counties, one of Romania''s best known wine districts. Iron rich red clays suit its reds, which are known above all for Fetească Neagră.',
   null, null, null, null, 'The name may be followed by one of eight official sub-designations, such as Dealu Mare-Urlați, and then by a single vineyard name.',
   null, 'published'),
  ('wr_0215', 'Cotnari', '{}'::text[], 'RO', 47.403, 26.933, 14,
   'Vineyards in Iași County, in Romania''s historic Moldavia region, famous for golden sweet white wines touched by noble rot. Dry whites come from native grapes such as Fetească Albă and Frâncușă.',
   null, null, null, null, 'The label may add one of 24 official single vineyard names, such as Dealul Castel or Dealul Paraclis.',
   null, 'published'),
  ('wr_0216', 'Murfatlar', '{}'::text[], 'RO', 44.223, 28.174, 23,
   'Vineyards on limestone soils in Dobrogea, between the Danube and the Black Sea, among Romania''s sunniest and driest. Wines run from dry to sweet, including ripe reds and late harvest whites.',
   null, null, null, null, 'The sub-designation Medgidia or Cernavodă may accompany the name, and a single vineyard name such as Basarabi may be added.',
   null, 'published'),
  ('wr_0217', 'Melnik', '{}'::text[], 'BG', 41.567, 23.283, 30,
   'Warm valley vineyards in south western Bulgaria near the Greek border, open to Mediterranean influence and mostly on sandy soils over limestone. The reds, led by the local Melnik grapes, are spicy and peppery with firm tannins.',
   null, null, 4, null, 'Registered as Мелник; the PDO may also be labelled with the traditional term GKNP (guaranteed and controlled appellation of origin).',
   'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=uriserv:OJ.C_.2023.272.01.0009.01.ENG', 'published'),
  ('wr_0218', 'Sakar', '{}'::text[], 'BG', 41.768, 26.198, 30,
   'Vineyards at the foot of the Sakar mountain in Bulgaria''s Thracian Lowland. Red wines lead, chiefly from Merlot and Syrah.',
   null, null, null, null, 'Registered as Сакар; the PDO may also be labelled with the traditional term GKNP (guaranteed and controlled appellation of origin).',
   'https://webgate.ec.europa.eu/eambrosia-api/api/v1/attachments/26815', 'published'),
  ('wr_0219', 'Fruška Gora', '{}'::text[], 'RS', 45.203, 19.934, 30,
   'Vineyards cover the slopes of Fruška Gora, a low range above the Danube, whose nearness helps the grapes ripen. Soils are largely chernozem over loess, and Grašac, the local Welschriesling, has long been grown here.',
   null, null, null, null, 'Serbian quality wines with geographical origin are labelled K.P.K. (controlled origin and quality) or K.G.P.K. (controlled and guaranteed origin and quality, the top tier).',
   'https://faolex.fao.org/docs/pdf/srb153778.pdf', 'published'),
  ('wr_0220', 'Codru', '{}'::text[], 'MD', 47.224, 28.408, 30,
   'Hilly, forested country in central Moldova, where the woods temper a warm continental climate. Its light soils favour white wines, which make up most of the output, with Merlot also widely grown.',
   null, null, null, null, 'The main label must carry the wine category and the words cu indicație geografică protejată "Codru".',
   'https://wineofmoldova.com/wp-content/uploads/2020/12/215_28-12-2011-min.pdf', 'published'),
  ('wr_0221', 'Ștefan Vodă', '{}'::text[], 'MD', 46.513, 29.662, 30,
   'Moldova''s south eastern wine region, planted mainly on black earth soils rich in humus. It is above all a red wine region, built on Cabernet Sauvignon, Merlot and the local Rară Neagră.',
   null, null, null, null, 'Labels must state vin cu indicație geografică protejată "Ștefan Vodă"; a variety may be named when it makes up at least 85% of the wine.',
   'https://wineofmoldova.com/wp-content/uploads/2020/12/188_12-10-2011-min.pdf', 'published'),
  ('wr_0222', 'Valul lui Traian', '{}'::text[], 'MD', 45.905, 28.195, 30,
   'Moldova''s south western wine region is mainly known for red wines. Merlot and Cabernet Sauvignon are the leading grapes, with Fetească Neagră among the local varieties grown there.',
   null, null, null, null, null,
   'https://wineofmoldova.com/valul-lui-traian/', 'published'),
  ('wr_0223', 'Rapsani', '{"Ραψάνη"}'::text[], 'GR', 39.889, 22.559, 6,
   'A small red wine zone on the slopes of Mount Olympus in Thessaly. Its wines blend Xinomavro with two local red grapes, Krasato and Stavroto.',
   null, null, null, null, 'Réserve needs two years of ageing, at least twelve months in oak and six in bottle. Grande Réserve needs four years, at least eighteen months in oak and eighteen in bottle.',
   'https://winesofgreece.org/pdo/pdo-rapsani/', 'published'),
  ('wr_0224', 'Mantinia', '{"Μαντινεία","Mantineia"}'::text[], 'GR', 37.577, 22.440, 14,
   'A high, cool plateau around Tripoli in Arcadia, in the central Peloponnese, where the harvest comes late. It makes aromatic, crisp dry and sparkling whites from the pink skinned Moschofilero.',
   null, null, null, null, 'Réserve needs a year of ageing, at least six months in oak and three in bottle. Grande Réserve needs two years, at least twelve months in oak and six in bottle.',
   'https://winesofgreece.org/pdo/pdo-mantinia/', 'published'),
  ('wr_0225', 'Goumenissa', '{"Γουμένισσα"}'::text[], 'GR', 40.948, 22.438, 8,
   'A small red wine zone on the south eastern foothills of Mount Paiko in Kilkis, Macedonia. Xinomavro is blended with at least 20% Negoska, which makes the wines fruitier and rounder than those of Naoussa.',
   4, null, null, null, 'Réserve needs two years of ageing, at least twelve months in oak and six in bottle. Grande Réserve needs four years, at least eighteen months in oak and eighteen in bottle.',
   'https://winesofgreece.org/pdo/pdo-goumenissa/', 'published'),
  ('wr_0226', 'Patras', '{"Patra","Πάτρα"}'::text[], 'GR', 38.089, 21.665, 23,
   'The hills and coast of Achaia around the city of Patras, in the northern Peloponnese. Dry whites come from Roditis in the hill country, and sweet wines from Mavrodaphne and Muscat around the city.',
   null, null, null, null, 'Mavrodaphni of Patra spends at least a year in oak casks of up to 1,000 litres. Reserve needs three years of ageing in all, Vieille Reserve five and Grand Reserve seven, each with set time in cask and in bottle.',
   'https://winesofgreece.org/pdo/pdo-patras/', 'published'),
  ('wr_0227', 'Drama', '{"Δράμα"}'::text[], 'GR', 41.285, 24.156, 33,
   'A PGI covering the whole regional unit of Drama in northern Greece. It is best known for blending Greek and international grapes, above all white blends of Sauvignon Blanc with Assyrtiko.',
   null, null, null, null, null,
   'https://ec.europa.eu/geographical-indications-register/eambrosia-public-api/api/v1/attachments/11853', 'published'),
  ('wr_0228', 'Paros', '{"Πάρος"}'::text[], 'GR', 37.054, 25.190, 9,
   'A Cycladic island where the white Monemvasia makes the dry whites and, unusually, is blended with the red Mandilaria for the reds. Malvasia Paros is a sweet wine from sun dried grapes.',
   null, null, null, null, 'Malvasia Paros needs at least 24 months of oxidative ageing in oak. Longer ageing may be stated only as 4, 8, 12 or more years, in steps of four.',
   'https://winesofgreece.org/pdo/pdo-paros/', 'published'),
  ('wr_0229', 'Monemvasia', '{"Monemvasia - Malvasia","Μονεμβασία"}'::text[], 'GR', 36.677, 22.946, 15,
   'The south eastern tip of Laconia in the Peloponnese, around Monemvasia. Its PDO, created in 2010, revives the historic sweet Malvasia wine made from sun dried grapes.',
   null, null, null, null, 'Monemvasia and Malvasia must appear together in the same size and colour, Malvasia always in Latin letters. Ageing may be stated only as 4, 8, 12 or more years, in steps of four.',
   'https://winesofgreece.org/pdo/pdo-monemvassia-malvasia/', 'published'),
  ('wr_0230', 'Samos', '{"Σάμος"}'::text[], 'GR', 37.733, 26.812, 30,
   'An eastern Aegean island whose PDO covers sweet wines from Muscat Blanc à Petits Grains, in styles from vin doux and fortified vin doux naturel to wines from sun dried grapes.',
   null, null, null, null, null,
   'https://winesofgreece.org/pdo/pdo-samos/', 'published'),
  ('wr_0231', 'Commandaria', '{"Κουμανδαρία"}'::text[], 'CY', 34.828, 32.975, 7,
   'A sweet amber wine from fourteen villages in the hills north of Limassol, made from sun dried Xynisteri and Mavro grapes and aged at least two years in oak.',
   null, null, null, null, 'The grapes are sun dried before pressing and the wine is aged at least two years in oak casks. It may be fortified.',
   'https://lisbon-express.wipo.int/pdf/CRTINF_25557_Current%20information%20-%20AO-1240.pdf', 'published'),
  ('wr_0232', 'Krasochoria Lemesou', '{"Κρασοχώρια Λεμεσού","Krasohoria Lemesou"}'::text[], 'CY', 34.848, 32.809, 30,
   'Hill villages of Limassol district whose PDO covers vineyards at 600 m and above. Whites are built on Xynisteri, while reds draw on Maratheftiko, Mavro and international grapes such as Syrah.',
   null, null, null, null, 'Red wines from Maratheftiko must age at least six months in oak barrels.',
   'https://ec.europa.eu/geographical-indications-register/eambrosia-public-api/api/v1/attachments/11875', 'published'),
  ('wr_0233', 'Vayots Dzor', '{}'::text[], 'AM', 39.722, 45.184, 30,
   'Armenia''s highest wine region, in the south of the country. It is the home of Areni, the country''s leading red grape, which gives fresh, red fruited wines here.',
   3, 4, 3, null, null,
   'https://wineanorak.com/2021/11/22/armenian-wine-a-brief-study/', 'published'),
  ('wr_0234', 'Galilee', '{}'::text[], 'IL', 33.017, 35.489, 30,
   'Upper and Lower Galilee in northern Israel, with Upper Galilee vineyards at roughly 400 to 900 metres on basalt, limestone and terra rossa soils. Altitude brings a cooler climate and a longer ripening season.',
   null, null, null, null, null,
   'https://www.winetourism.com/wine-regions/israel-wine-regions/galille/', 'published'),
  ('wr_0235', 'Judean Hills', '{}'::text[], 'IL', 31.774, 35.073, 30,
   'High vineyards in the hills west of Jerusalem, planted on terra rossa, clay and limestone. Cool summer nights and a sharp drop in temperature after dark help the grapes ripen while keeping their acidity.',
   null, null, null, null, null,
   'https://castel.co.il/en/?p=5784', 'published'),
  ('wr_0236', 'Negev', '{}'::text[], 'IL', 30.609, 34.801, 30,
   'Israel''s southern desert, where irrigated vineyards in the highlands near Mitzpe Ramon sit at about 800 metres on loess. Hot days and cold nights shape the wines, and its whites are often singled out.',
   null, null, null, null, null,
   'https://www.jpost.com/israel-news/wine-talk-desert-wine-679470', 'published'),
  ('wr_0237', 'Thrace', '{"Trakya"}'::text[], 'TR', 40.668, 27.246, 30,
   'Turkey''s corner of Europe, between Istanbul and the Greek and Bulgarian borders, with vineyards close to three seas. Bordeaux grapes do well here alongside the local red Papazkarası.',
   null, null, null, null, null,
   'https://www.decanter.com/wine-news/opinion/jefford-on-monday/jefford-on-monday-the-turkish-renaissance-23836', 'published'),
  ('wr_0238', 'Cappadocia', '{"Kapadokya"}'::text[], 'TR', 38.630, 34.912, 30,
   'High vineyards on volcanic tuff soils in central Anatolia, with a continental climate and wide swings between day and night. Its signature grape is the white Emir, which gives high acid, mineral wines.',
   null, null, null, null, null,
   'https://www.decanter.com/premium/a-new-taste-of-turkish-wine-435840/', 'published');

insert into public.grapes
  (grape_code, name, aliases, colour, summary, tastes, aged_note,
   body, acidity, tannin, publication_status)
values
  ('gr_0147', 'Fetească Neagră', '{"Păsărească Neagră","Coada Rândunicii","Poama Fetei Neagră","Schwarze Mädchentraube"}'::text[], 'red',
   'Romania''s best known native red grape, closely tied to Dealu Mare. It makes medium to full bodied reds with plum and spice that grow richer with age.',
   '{"Plum","Spice"}'::text[], 'The best wines age well and grow richer.', 3, null, null, 'published'),
  ('gr_0148', 'Fetească Albă', '{"Păsărească Albă","Poama Fetei","Leányka","Mädchentraube"}'::text[], 'white',
   'A white grape native to Romania and also grown in Moldova. It is used for still and sparkling wines with delicate floral and citrus aromas.',
   '{"Floral","Citrus"}'::text[], null, null, null, null, 'published'),
  ('gr_0149', 'Fetească Regală', '{"Dănășană","Galbenă de Ardeal","Királyleányka","Königliche Mädchentraube"}'::text[], 'white',
   'A white grape that appeared in Romania in the 1920s, with Fetească Albă as one parent. It makes fresh white wines with floral aromas.',
   '{"Floral"}'::text[], null, null, null, null, 'published'),
  ('gr_0150', 'Grasă de Cotnari', '{"Grasă","Kövérszőlő","Dicktraube"}'::text[], 'white',
   'A white grape from Cotnari in Romania''s Moldavia region. It is best known for sweet, golden wines made from grapes touched by noble rot.',
   '{}'::text[], 'Ages well, its colour deepening toward amber.', null, null, null, 'published'),
  ('gr_0151', 'Frâncușă', '{"Mustoasă de Moldova","Vinoasă","Poamă Creață","Mildweisser"}'::text[], 'white',
   'A white grape native to Romania and traditional in Cotnari, where it goes into both still and sparkling wines.',
   '{}'::text[], null, null, null, null, 'published'),
  ('gr_0152', 'Băbească Neagră', '{"Rară Neagră","Căldărușă","Crăcană","Serecsia","Grossmuttertraube"}'::text[], 'red',
   'An old red grape of Romania and Moldova, where it is called Rară Neagră. It gives pale, light bodied reds with high acidity.',
   '{}'::text[], null, 2, 4, null, 'published'),
  ('gr_0153', 'Muscat Ottonel', '{"Muscat Ottonel Blanc","Muskotály","Misket Ottonel"}'::text[], 'white',
   'A white Muscat grape that originated in France, with Chasselas as one parent. In Romania it is grown in regions including Dealu Mare and Murfatlar.',
   '{}'::text[], null, null, null, null, 'published'),
  ('gr_0154', 'Pálava', '{"Nema","Veverka"}'::text[], 'white',
   'A Moravian crossing of Traminer and Müller-Thurgau, bred by Josef Veverka in 1953, giving golden, full bodied aromatic whites close in style to Gewürztraminer.',
   '{"Nutmeg","Vanilla","Mandarin"}'::text[], null, 4, null, null, 'published'),
  ('gr_0155', 'Muškát moravský', '{"Moravian Muscat","Mopr"}'::text[], 'white',
   'A Moravian crossing of Muscat Ottonel and Prachttraube from the Polešovice breeding station, registered in 1987, giving light coloured whites with a clear muscat scent.',
   '{"Muscat"}'::text[], null, null, null, null, 'published'),
  ('gr_0156', 'Shiroka Melnishka', '{"Shiroka Melnishka Loza","Melnik","Broadleaf Melnik"}'::text[], 'red',
   'A Bulgarian red grape grown almost only in the Struma valley near the Greek border, giving spicy, peppery wines with dark fruit.',
   '{"Black pepper","Spice","Black fruit"}'::text[], null, null, null, null, 'published'),
  ('gr_0157', 'Ranna Melnishka Loza', '{"Melnik 55","Early Melnik"}'::text[], 'red',
   'A Bulgarian crossing of Shiroka Melnishka and the French Valdiguié, grown almost only in the Struma valley. Its name means Early Melnik.',
   '{}'::text[], null, null, null, null, 'published'),
  ('gr_0158', 'Moschofilero', '{}'::text[], 'white',
   'A pink skinned Greek grape made mostly into aromatic, crisp dry whites, with some sparkling and rosé. Its home is the high Mantinia plateau in Arcadia.',
   '{"Rose petal","Citrus","Peach"}'::text[], 'Mostly drunk young, though some gain from a few years in bottle.', 2, 4, null, 'published'),
  ('gr_0159', 'Roditis', '{}'::text[], 'white',
   'Greece''s most planted white grape, pink skinned and grown across much of the country. At low yields it gives citrus, mineral dry whites; it is the grape of PDO Patra.',
   '{"Citrus","Mineral"}'::text[], null, 2, null, null, 'published'),
  ('gr_0160', 'Mavrodaphne', '{"Mavrodafni","Μαυροδάφνη"}'::text[], 'red',
   'A dark red grape of the north western Peloponnese and Kefalonia, long used for sweet fortified wines such as Mavrodaphni of Patra. Dry versions are now drawing attention.',
   '{"Dried fruit"}'::text[], null, null, null, null, 'published'),
  ('gr_0161', 'Negoska', '{"Popolka"}'::text[], 'red',
   'A dark, soft red grape from northern Greece, now grown mainly on the slopes of Mount Paiko. It is blended with Xinomavro in Goumenissa to add colour and roundness.',
   '{"Chocolate"}'::text[], null, null, 3, null, 'published'),
  ('gr_0162', 'Malagousia', '{}'::text[], 'white',
   'A Greek white grape rescued from near extinction and now planted across the country. It gives aromatic, full bodied whites, mostly dry, with some sweet ones.',
   '{"Peach","Floral"}'::text[], null, 4, null, null, 'published'),
  ('gr_0163', 'Monemvasia', '{"Monemvassia"}'::text[], 'white',
   'A white grape named after the Laconian port of Monemvasia but grown today mostly on Paros. It makes dry whites there and sweet Malvasia wines from sun dried grapes.',
   '{"Citrus","Mineral"}'::text[], null, null, null, null, 'published'),
  ('gr_0164', 'Mandilaria', '{"Mandilari","Amorgiano"}'::text[], 'red',
   'A red grape of Crete and the Aegean islands that gives deeply coloured, tannic wine. It is mostly blended, with Monemvasia on Paros and with Kotsifali on Crete.',
   '{"Leather"}'::text[], 'Benefits from a few years in bottle.', null, 4, 5, 'published'),
  ('gr_0165', 'Xynisteri', '{"Xinisteri","Ξυνιστέρι"}'::text[], 'white',
   'The most planted white grape of Cyprus, giving delicate, fresh whites with citrus and stone fruit notes, at its best from high vineyards. One of the two Commandaria grapes.',
   '{"Lemon","Stone fruit","White flowers","Herbs"}'::text[], 'Good examples can age, gaining complexity over several years in bottle.', null, null, null, 'published'),
  ('gr_0166', 'Mavro', '{"Local Mavro"}'::text[], 'red',
   'The most planted grape of Cyprus, a red that tends to give pale, lighter wines with red fruit and soft tannins. With Xynisteri it makes the sweet Commandaria.',
   '{"Red fruit"}'::text[], null, 2, null, 2, 'published'),
  ('gr_0167', 'Maratheftiko', '{"Vamvakada"}'::text[], 'red',
   'A rare red native to Cyprus whose vines cannot pollinate themselves and need partner vines. Its wines show violet, cherry and dark berry fruit with firm tannins.',
   '{"Violet","Cherry","Blackberry"}'::text[], 'Good examples are built to age over the medium to long term, with or without oak.', 3, null, 4, 'published'),
  ('gr_0168', 'Areni', '{"Areni Noir","Areni Noire","Sev Areni"}'::text[], 'red',
   'Armenia''s most celebrated red grape, thick skinned and closely tied to Vayots Dzor. It gives fresh, red fruited wines that are structured but not heavily tannic.',
   '{"Cherry","Plum","Black pepper and spice"}'::text[], 'Oak aged and older examples gain depth and tertiary notes.', 3, 4, 3, 'published'),
  ('gr_0169', 'Voskehat', '{}'::text[], 'white',
   'Armenia''s leading native white grape. It makes crisp, fresh wines with citrus, orchard fruit and floral notes, and a certain weight and texture.',
   '{"Citrus","Pear","White flowers"}'::text[], null, 3, 3, null, 'published'),
  ('gr_0170', 'Petit Verdot', '{}'::text[], 'red',
   'A red grape from Bordeaux, used there in small amounts for blending, that gives deep colour and full bodied, firm wines with violet perfume.',
   '{"Violet","Black cherry","Plum","Lilac"}'::text[], 'Ages well; time softens its firm structure.', 5, 3, 4, 'published'),
  ('gr_0171', 'Öküzgözü', '{}'::text[], 'red',
   'A red grape from Elazığ in eastern Anatolia, named for its large dark berries. It gives fruity reds and is often blended with Boğazkere.',
   '{"Cherry","Berry fruit","Spice","Herbs"}'::text[], null, 3, 4, 3, 'published'),
  ('gr_0172', 'Boğazkere', '{"Bogazkere"}'::text[], 'red',
   'A thick skinned red grape from Diyarbakır in eastern Turkey. It makes dark, firmly tannic reds and is often blended with Öküzgözü.',
   '{"Cherry","Mulberry","Spice","Leather"}'::text[], 'Made to age; its firm tannins need time in bottle.', 4, null, 5, 'published'),
  ('gr_0173', 'Kalecik Karası', '{"Kalecik Karasi"}'::text[], 'red',
   'A red grape from Kalecik near Ankara in central Anatolia. It makes pale, light reds with fresh red fruit.',
   '{"Cherry","Raspberry"}'::text[], null, 2, null, null, 'published'),
  ('gr_0174', 'Narince', '{}'::text[], 'white',
   'A white grape from Tokat in Anatolia. It gives rounder, fuller whites with citrus and yellow fruit, often fermented or matured in oak.',
   '{"Citrus","Yellow fruit","Floral","Orange"}'::text[], 'Often fermented in oak and aged on its lees, which gives a rounder, richer wine.', 4, null, null, 'published'),
  ('gr_0175', 'Emir', '{}'::text[], 'white',
   'A white grape native to Cappadocia in central Anatolia. It makes light, high acid whites with green apple and mineral notes, both still and sparkling.',
   '{"Green apple","Citrus","Mineral"}'::text[], null, 2, 4, null, 'published'),
  ('gr_0176', 'Papazkarası', '{"Papaskarasi"}'::text[], 'red',
   'A local red grape of Turkish Thrace, grown around Kırklareli and Edirne. It is made as red wine and also as a white blanc de noirs.',
   '{}'::text[], null, null, null, null, 'published'),
  ('gr_0177', 'Kınalı Yapıncak', '{}'::text[], 'white',
   'A local white grape of Şarköy and Mürefte in Tekirdağ, on the Turkish side of Thrace. Its wines show pear among their fruit notes.',
   '{"Pear"}'::text[], null, null, null, null, 'published');

update public.grapes g set similar_grape_id = s.id, similar_note = 'A Traminer offspring with a similar aromatic profile.' from public.grapes s where s.grape_code = 'gr_0041' and g.grape_code = 'gr_0154';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Writers often compare it with Pinot Noir.' from public.grapes s where s.grape_code = 'gr_0001' and g.grape_code = 'gr_0168';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Its firm tannins are often compared with Nebbiolo.' from public.grapes s where s.grape_code = 'gr_0009' and g.grape_code = 'gr_0172';
update public.grapes g set similar_grape_id = s.id, similar_note = 'Writers liken it to Pinot Noir for its light, red fruited style.' from public.grapes s where s.grape_code = 'gr_0001' and g.grape_code = 'gr_0173';
update public.grapes set aliases = aliases || '{"Tămâioasă Românească","White Muscat","Moschoudi","Muscat Samos"}'::text[] where grape_code = 'gr_0050';
update public.grapes set aliases = aliases || '{"Burgund Mare"}'::text[] where grape_code = 'gr_0040';
update public.grapes set aliases = aliases || '{"Riesling Italian","Ryzlink vlašský","Grašac","Italijanski rizling"}'::text[] where grape_code = 'gr_0039';
update public.grapes set aliases = aliases || '{"Ryzlink rýnský"}'::text[] where grape_code = 'gr_0008';
