  ('wa_0712', 'Samos', '{}'::text[], 'wr_0230', 'white', 'PDO for sweet Muscat: vin doux, fortified vin doux naturel with a Grand Cru version from selected vineyards, and naturally sweet wine from sun dried grapes.', 1),
  ('wa_0713', 'Commandaria', '{}'::text[], 'wr_0231', 'mixed', 'Sweet amber PDO wine from sun dried white Xynisteri and red Mavro grapes, made as a liqueur wine or a wine from sun dried grapes.', 1),
  ('wa_0714', 'Krasohoria Lemesou', '{}'::text[], 'wr_0232', 'mixed', 'PDO for wines from vineyards at 600 m and above in named villages of Limassol district.', 1),
  ('wa_0715', 'Krasohoria Lemesou - Afames', '{}'::text[], 'wr_0232', 'mixed', 'Sub area for vineyards at 750 m and above in Vouni, Kilani, Mandria and Omodos, east of the Cha Potami river.', 2),
